<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {api,getRun} from '../api'
import RunWorkspacePanel from './RunWorkspacePanel.vue'
const emit=defineEmits<{(e:'open-session',id:string):void}>()
const props=defineProps<{initialSection?:string}>()
type Row=Record<string,any>
const section=ref(props.initialSection||'mcp'),error=ref(''),notice=ref(''),busy=ref(false)
const connections=ref<Row[]>([]),schedules=ref<Row[]>([]),tasks=ref<Row[]>([]),notifications=ref<Row[]>([]),memories=ref<Row[]>([]),projects=ref<Row[]>([])
const selectedRun=ref('')
const mcpName=ref(''),url=ref(''),key=ref(''),discovered=ref<Row[]>([]),discoveryId=ref('')
const name=ref(''),prompt=ref(''),interval=ref(1440),first=ref(new Date(Date.now()+60000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)),project=ref('')
const price=ref(0),threshold=ref(100000),estimateNote=ref(''),sandbox=ref<Row>({}),history=ref<Row|null>(null),editing=ref<Row|null>(null),memoryContent=ref('')
let timer:ReturnType<typeof setInterval>|undefined,disposed=false
async function refresh(){try{const [m,s,u,n,p,b,mm]=await Promise.all([api.get<Row>('/api/operations/mcp'),api.get<Row>('/api/operations/schedules'),api.get<Row>('/api/operations/usage'),api.get<Row>('/api/operations/notifications'),api.get<Row>('/api/projects'),api.get<Row>('/api/operations/sandbox'),api.get<Row>('/api/operations/memories')]);if(disposed)return;connections.value=m.connections;schedules.value=s.schedules;tasks.value=u.tasks;if(!selectedRun.value&&u.tasks.length)selectedRun.value=u.tasks[0].id;notifications.value=n.notifications;projects.value=p.projects;sandbox.value=b;memories.value=mm.memories;price.value=Number(u.settings.price_per_million);threshold.value=Number(u.settings.reminder_tokens);estimateNote.value=u.estimateNote}catch(e){error.value=(e as Error).message}}
async function act(action:()=>Promise<unknown>,message='已保存'){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action();notice.value=message;await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function addMcp(){await act(async()=>{await api.post('/api/operations/mcp',{name:mcpName.value,url:url.value,apiKey:key.value,enabled:true});key.value='';mcpName.value='';url.value=''},'MCP连接已保存；点击测试发现工具')}
async function testMcp(id:string){await act(async()=>{discovered.value=(await api.post<Row>(`/api/operations/mcp/${id}/test`)).tools;discoveryId.value=id},'已完成MCP握手和工具发现')}
async function addSchedule(){await act(async()=>{await api.post('/api/operations/schedules',{name:name.value,prompt:prompt.value,intervalMinutes:interval.value,nextAt:new Date(first.value).toISOString(),projectId:project.value||null});name.value='';prompt.value=''},'定时任务已启用，执行需要后端和虚拟机在线')}
async function openNotification(row:Row){await act(()=>api.post(`/api/operations/notifications/${row.id}/read`),'已读');if(row.run_id){const run=await getRun(row.run_id);emit('open-session',run.sessionId)}}
async function memoryHistory(row:Row){await act(async()=>{history.value=await api.get<Row>(`/api/operations/memories/${row.id}/history`);editing.value=row;memoryContent.value=row.content},'已加载来源与历史')}
async function saveMemory(){if(!editing.value)return;await act(()=>api.put(`/api/operations/memories/${editing.value!.id}`,{content:memoryContent.value,expire:false}),'已将确认的内容保存为明确记忆');history.value=null;editing.value=null}
function time(value:string){return value?new Date(value).toLocaleString('zh-CN'):''}
onMounted(()=>{refresh();timer=setInterval(async()=>{try{const n=await api.get<Row>('/api/operations/notifications');if(!disposed)notifications.value=n.notifications}catch{/* Keep the last notification list while offline. */}},15000)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
</script>
<template>
 <div class="operations-page">
  <header><div><span class="eyebrow">AGENT WORKBENCH</span><h1>{{ ({mcp:'MCP 连接',plans:'任务计划',schedules:'定时任务',usage:'运行与费用',memories:'记忆来源',notifications:'任务通知'} as Record<string,string>)[section]||'工作台' }}</h1><p>连接工具，安排任务，管理运行与知识来源。</p></div><button class="btn" :disabled="busy" @click="refresh">刷新</button></header>

  <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="muted" role="status">{{ notice }}</p>
  <section v-if="section==='mcp'" class="ops-grid">
   <form class="card" @submit.prevent="addMcp"><h2>添加 MCP 服务</h2><p>支持 Streamable HTTP。粘贴服务端点和可选 Key，测试后 Agent 可发现并调用工具。调用可能修改外部数据，会逐次申请批准。</p><label>连接名称<input v-model="mcpName" class="field" required maxlength="80" placeholder="例如 GitHub 或数据库" /></label><label>MCP 端点<input v-model="url" class="field" type="url" required placeholder="https://example.com/mcp" /></label><label>API Key（可选）<input v-model="key" class="field" type="password" autocomplete="new-password" placeholder="本地加密保存，页面不回显" /></label><button class="btn btn-primary" :disabled="busy">保存连接</button><small>本机可使用 http://127.0.0.1；远程需要 HTTPS。暂不支持 stdio 与 OAuth 登录。</small></form>
   <div><article v-for="c in connections" :key="c.id" class="card"><h3>{{ c.name }} <span class="badge">{{ c.enabled?'已启用':'已停用' }}</span></h3><p class="mono">{{ c.url }}</p><div class="actions"><button class="btn" :disabled="busy||!c.enabled" @click="testMcp(c.id)">测试 / 发现工具</button><button class="btn" :disabled="busy" @click="act(()=>api.put('/api/operations/mcp/'+c.id,{enabled:!c.enabled}))">{{ c.enabled?'停用':'启用' }}</button><button class="btn" :disabled="busy" @click="act(()=>api.del('/api/operations/mcp/'+c.id),'连接已删除')">删除</button></div><details v-if="discoveryId===c.id" open><summary>发现 {{ discovered.length }} 个工具</summary><div v-for="tool in discovered" :key="tool.name" class="remote-tool"><strong>{{ tool.name }}</strong><p>{{ tool.description }}</p><pre>{{ JSON.stringify(tool.inputSchema,null,2) }}</pre></div></details></article><p v-if="!connections.length" class="empty">尚未配置 MCP 服务。</p></div>
  </section>
  <section v-else-if="section==='plans'"><div class="card"><h2>查看任务计划</h2><p>选择任务可查看步骤、失败位置、修改预览和授权；后续步骤可在任务面板中调整。</p><select v-model="selectedRun" class="field" aria-label="选择计划任务"><option v-for="r in tasks" :key="r.id" :value="r.id">{{ r.title||'新会话' }} · {{ r.status }} · {{ r.id.slice(0,8) }}</option></select><RunWorkspacePanel v-if="selectedRun" :key="selectedRun" :run-id="selectedRun" :status="tasks.find(r=>r.id===selectedRun)?.status||''" answer="" @retried="id=>{selectedRun=id;refresh()}" /><p v-else class="empty">暂无任务，请先创建会话并发送任务。</p></div></section>
  <section v-else-if="section==='schedules'" class="ops-grid">
   <form class="card" @submit.prevent="addSchedule"><h2>安排重复任务</h2><label>名称<input v-model="name" class="field" required maxlength="100" /></label><label>任务内容<textarea v-model="prompt" class="field" required rows="5" maxlength="8000" placeholder="每天整理资料，生成报告；需要外部操作时仍遵守任务授权。" /></label><label>项目<select v-model="project" class="field"><option value="">普通会话 / 专属工作区</option><option v-for="p in projects" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><div class="ops-grid"><label>首次执行（本地时间）<input v-model="first" class="field" type="datetime-local" required /></label><label>间隔（分钟）<input v-model.number="interval" class="field" type="number" min="5" max="525600" required /></label></div><button class="btn btn-primary" :disabled="busy">创建并启用</button><small>后端在线时执行，停机错过的多次间隔合并为一次。需要审批或补充输入时暂停并通知，不会无人确认地扩大权限。</small></form>
   <div><article v-for="s in schedules" :key="s.id" class="card"><h3>{{ s.name }} <span class="badge">{{ s.enabled?'已启用':'已暂停' }}</span></h3><p>{{ s.prompt }}</p><p class="muted">每 {{ s.interval_minutes }} 分钟 · 下次 {{ time(s.next_at) }}</p><div class="actions"><button class="btn" @click="emit('open-session',s.session_id)">查看会话</button><button class="btn" :disabled="busy" @click="act(()=>api.put('/api/operations/schedules/'+s.id,{enabled:!s.enabled}))">{{ s.enabled?'暂停':'启用' }}</button><button class="btn" :disabled="busy" @click="act(()=>api.del('/api/operations/schedules/'+s.id),'定时任务已删除')">删除</button></div></article><p v-if="!schedules.length" class="empty">还没有定时任务。</p></div>
  </section>
  <section v-else-if="section==='usage'">
   <form class="card settings" @submit.prevent="act(()=>api.put('/api/operations/usage',{price,reminderTokens:threshold}))"><label>估算单价（元 / 百万 Token）<input v-model.number="price" class="field" type="number" min="0" max="100000" step="0.01" /></label><label>单任务提醒额度（Token）<input v-model.number="threshold" class="field" type="number" min="1" /></label><button class="btn btn-primary" :disabled="busy">保存提醒</button><small>{{ estimateNote }}</small></form>
   <div class="card table-wrap"><table><thead><tr><th>会话 / 任务</th><th>状态</th><th>模型 / 工具调用</th><th>Token</th><th>耗时</th><th>估算费用</th></tr></thead><tbody><tr v-for="r in tasks" :key="r.id" :class="{reminded:r.reminderReached}"><td><button class="text-link" @click="emit('open-session',r.session_id)">{{ r.title||'新会话' }}</button><small>{{ r.id.slice(0,8) }}</small></td><td>{{ r.status }}<small v-if="r.reason_code">{{ r.reason_code }}</small></td><td>{{ r.model_calls }} / {{ r.tool_calls }}</td><td>{{ r.token_used.toLocaleString() }} <small v-if="r.reminderReached">已达到提醒额度</small></td><td>{{ r.seconds }} 秒</td><td>¥ {{ Number(r.estimatedCost).toFixed(4) }}</td></tr></tbody></table><p v-if="!tasks.length" class="empty">暂无运行记录。</p></div>
   <div class="card"><h3>隔离命令环境</h3><p>{{ sandbox.note }}</p><small>镜像：{{ sandbox.image }} · SSH 配置：{{ sandbox.sshKeyAvailable?'已找到密钥文件（不代表服务已连通）':'缺少密钥文件' }} · 网络关闭 · 无主机目录挂载</small></div>
  </section>
  <section v-else-if="section==='memories'" class="ops-grid">
   <div><article v-for="m in memories" :key="m.id" class="card"><h3>{{ m.memory_key }} <span class="badge">{{ m.state==='revoked'?'已撤回':m.expired?'已过期':m.authority==='explicit'?'明确记忆':'AI 总结' }}</span></h3><p>{{ m.content }}</p><div class="actions"><button class="btn" :disabled="busy" @click="memoryHistory(m)">来源 / 历史 / 处理冲突</button><button v-if="!m.expired&&m.state==='active'" class="btn" :disabled="busy" @click="act(()=>api.put('/api/operations/memories/'+m.id,{expire:true}),'记忆已过期，不再召回')">设为过期</button></div></article><p v-if="!memories.length" class="empty">尚无长期记忆。</p></div>
   <div v-if="history&&editing" class="card"><h2>{{ editing.memory_key }}</h2><label>确认后的内容<textarea v-model="memoryContent" class="field" rows="5" maxlength="2000" /></label><button class="btn btn-primary" :disabled="busy||!memoryContent.trim()" @click="saveMemory">确认此内容为当前记忆</button><h3>来源会话</h3><div v-for="s in history.sources" :key="s.session_id+':'+s.source_seq+':'+s.memory_version" class="history-row"><button class="text-link" @click="emit('open-session',s.session_id)">{{ s.title||'来源会话' }} · 消息 {{ s.source_seq }}</button><p>{{ s.evidence }}</p><small>记忆版本 {{ s.memory_version }}</small></div><p v-if="!history.sources.length" class="muted">此记忆没有对话来源记录，可能由手动保存创建。</p><h3>历次内容</h3><div v-for="h in history.history" :key="h.id" class="history-row"><p>{{ h.content }}</p><small>版本 {{ h.version }} · {{ time(h.created_at) }}</small><button class="btn btn-sm" @click="memoryContent=h.content">选择此版本内容</button></div><small>历史从本次更新起记录。同键内容更新可在此核对；跨键语义冲突暂不自动裁决。</small></div>
  </section>
  <section v-else><article v-for="n in notifications" :key="n.id" class="card notification" :class="{unread:!n.read_at}"><div><h3>{{ n.title }}</h3><small>{{ time(n.created_at) }}</small></div><button class="btn" :disabled="busy" @click="openNotification(n)">{{ n.run_id?'查看任务':'标为已读' }}</button></article><p v-if="!notifications.length" class="empty">暂无通知。完成、失败或需要处理的定时任务会出现在这里。</p></section>
 </div>
</template>
<style scoped>
.operations-page{padding:32px 40px;overflow:auto;height:100%;color:var(--txt-1);font-size:13px}.operations-page header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}h1{font-size:28px;margin:7px 0}h2{font-size:18px;margin:0 0 15px}h3{font-size:14px;margin:0 0 10px}p{line-height:1.8;color:var(--txt-2);overflow-wrap:anywhere}small{display:block;color:var(--txt-3);font-size:11px;line-height:1.8;margin-top:7px}.ops-tabs{display:flex;gap:8px;margin-bottom:24px;flex-wrap:wrap}.ops-tabs .selected{background:var(--amber-soft);color:var(--txt-1)}.ops-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:start}.card{padding:24px;margin-bottom:16px;min-width:0}.field{width:100%;margin:7px 0 12px}label{display:block;color:var(--txt-2);font-size:12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.error{color:var(--red);background:var(--red-soft);padding:12px;border-radius:8px}pre{max-height:260px;overflow:auto;white-space:pre-wrap;font-size:11px;background:var(--ink-1);padding:12px;border-radius:8px}.remote-tool,.history-row{padding:12px 0;border-bottom:1px solid var(--line)}.settings{display:grid;grid-template-columns:1fr 1fr auto;gap:18px;align-items:center}.settings small{grid-column:1/-1}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid var(--line);font-size:12px;vertical-align:top}th{color:var(--txt-3);font-weight:500}.text-link{border:0;background:transparent;padding:0;color:var(--txt-1);cursor:pointer;text-align:left;font-size:inherit}.text-link:hover{text-decoration:underline}.notification{display:flex;align-items:center;justify-content:space-between}.notification.unread{border-left:3px solid var(--green)}.reminded{background:var(--amber-soft)}.empty{padding:32px;text-align:center;color:var(--txt-3)}@media(max-width:1100px){.ops-grid{grid-template-columns:1fr}.operations-page{padding:24px}.settings{grid-template-columns:1fr 1fr}}
</style>
